pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address to, uint256 depositAmount) public {
        vm.assume(to != address(0));
        vm.assume(to != address(c));
        depositAmount = bound(depositAmount, 1, 1e18);

        // Deposit some ether into the contract
        vm.deal(address(this), depositAmount);
        c.deposit{value: depositAmount}();

        // Record balance before migrateTo
        uint256 balBefore = address(c).balance;

        // Call migrateTo as the creator
        vm.prank(address(0)); // creator is address(0) because no constructor call? Actually constructor sets msg.sender
        // We need to know creator address; in setUp, msg.sender is address(this) which is the test contract
        // So we must use address(this) as creator
        vm.prank(address(this));
        c.migrateTo(to);

        // Rule: after migrateTo, the contract balance should be unchanged if the buggy version transfers 0
        // In the reference, it transfers the whole balance, so balance becomes 0.
        // But in the buggy version, it transfers 0, so balance remains the same.
        // So the rule is: balance after migrateTo is either 0 (ref) or unchanged (bug).
        // Instead, we check a property that holds for reference and fails for bug:
        // The balance is reduced by the full balance (i.e., becomes 0) in reference, but not in bug.
        // So assert: balAfter == 0 for reference, but for bug it's >0.
        uint256 balAfter = address(c).balance;
        assertTrue(balAfter == 0, "Balance should be zero after migrateTo");
    }
}

