pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address depositor) public {
        vm.assume(depositor != address(0) && depositor != address(c) && depositor != 0x0000000000000000000000000000000000000001);
        // Deposit 1 wei
        uint256 depositAmount = 1;
        vm.deal(depositor, depositAmount);
        vm.prank(depositor);
        c.deposit{value: depositAmount}();

        // The contract balance should equal the deposit (since withdraw/refund only affect user balances)
        // After migrateTo by the creator, the recipient should get the full balance
        address recipient = address(0x1234);
        uint256 balBefore = address(recipient).balance;
        vm.prank(address(0x0000000000000000000000000000000000000001)); // creator is 0x1 because of how Foundry deploys
        c.migrateTo(recipient);
        uint256 balAfter = address(recipient).balance;

        // The rule: the recipient receives exactly the contract's balance at the time of migration
        // For the reference, that's the full deposit (1 wei). For the mutant, it's always 1 wei regardless.
        assertTrue(balAfter - balBefore == address(c).balance);
    }
}

