pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address to, uint256 amount) public {
        vm.assume(amount > 0 && amount <= address(c).balance);
        vm.deal(address(c), amount);
        // Deposit from a random user
        address user = address(0x1234);
        vm.deal(user, amount);
        vm.prank(user);
        c.deposit{value: amount}();
        // Record balance before migrateTo
        uint256 balanceBefore = address(to).balance;
        // Only creator can call migrateTo
        vm.prank(address(this)); // This is the creator since setUp was called by this contract
        // Ensure to is not the zero address
        vm.assume(to != address(0));
        // The correct behavior: after migrateTo(to), to receives the contract balance
        c.migrateTo(to);
        uint256 balanceAfter = address(to).balance;
        // The general rule: the balance of `to` increases by the contract balance (which is amount)
        assertTrue(balanceAfter - balanceBefore == amount, "migrateTo should transfer to the given address");
    }
}

